import{MinistryDetail}from"./MinistryDetail.js";export function MinistryCard(i,n){const s=`ministry-detail-${n}`;return`\n        <div class="ministry-card" data-index="${n}">\n            <div class="ministry-card-header">\n                <div class="ministry-badge">${i.shortName}</div>\n                <div class="ministry-card-title">\n                    <h3>${i.name}</h3>\n                    <p class="ministry-category">${i.category}</p>\n                </div>\n            </div>\n            <div class="ministry-card-body">\n                <div class="ministry-minister">\n                    <span class="minister-label">Minister</span>\n                    <span class="minister-name">${i.minister}</span>\n                </div>\n                <p class="ministry-overview">${i.overview}</p>\n                <button class="ministry-expand-btn" aria-expanded="false" aria-controls="${s}" data-index="${n}">\n                    <span>View Details</span>\n                    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">\n                        <polyline points="4 6 8 10 12 6"></polyline>\n                    </svg>\n                </button>\n            </div>\n            <div class="ministry-detail-panel" id="${s}" hidden>\n                ${MinistryDetail(i)}\n            </div>\n        </div>\n    `}